function validate(input) {
  const [{ SecretSanta = [] }] = input;
  const givers = new Set(), receivers = new Set();
  for (const [giver, receiver, value] of SecretSanta) {
    if (giver === null || receiver === null || value === null) return 'Every column needs a value.';
    if (giver === receiver) return `Employee ${giver} gives to themselves.`;
    if (value <= 0) return 'gift_value must be positive.';
    if (givers.has(giver)) return `Employee ${giver} gives more than one gift.`;
    if (receivers.has(receiver)) return `Employee ${receiver} receives more than one gift.`;
    givers.add(giver); receivers.add(receiver);
  }
  for (const giver of givers) if (!receivers.has(giver)) return `Employee ${giver} gives but receives nothing.`;
  return null;
}

