function generate(rand, size) {
  const small = size === 'small';
  const pick = n => Math.floor(rand() * n);
  // Choose the employees: a few ids from a small pool, or up to 2,000 distinct ids.
  let count = small ? pick(9) : 1500 + pick(501);
  if (count === 1) count = 0;
  const pool = [];
  for (let id = 1; id <= (small ? 12 : 4000); id++) pool.push(id);
  for (let i = pool.length - 1; i > 0; i--) { const j = pick(i + 1); [pool[i], pool[j]] = [pool[j], pool[i]]; }
  const people = pool.slice(0, count);
  const values = small ? [10, 20, 30, 40] : null;
  const SecretSanta = [];
  // Cut the shuffled employees into cycles of at least two people.
  for (let at = 0; at < people.length;) {
    let length = 2 + pick(small ? 4 : 30);
    const left = people.length - at;
    if (length > left || left - length === 1) length = left;
    const cycle = people.slice(at, at + length);
    cycle.forEach((giver, i) => SecretSanta.push([giver, cycle[(i + 1) % length], values ? values[pick(values.length)] : 1 + pick(500)]));
    at += length;
  }
  for (let i = SecretSanta.length - 1; i > 0; i--) { const j = pick(i + 1); [SecretSanta[i], SecretSanta[j]] = [SecretSanta[j], SecretSanta[i]]; }
  return [{ SecretSanta }];
}
